                <div style="margin-top:.3rem;color:#555;font-size:.85rem;">
                    <?= implode(' · ', array_map(fn($i) => '✔ ' . $i, $security_items)) ?>
                </div>
                <?php if ($security_score < 3): ?>
                    <div style="margin-top:.5rem;color:#e65100;font-size:.85rem;">
