            'mes_demandes'    => ['href' => 'index.php?p=my_submissions', 'label' => 'Mes demandes',    'icon' => '📋'],
            'mes_validations' => ['href' => 'index.php?p=my_validations', 'label' => 'Mes validations', 'icon' => '✅'],
