            'dashboard'  => ['href' => 'index.php?p=dashboard',        'label' => 'Supervision',       'icon' => '📊'],
            'settings'   => ['href' => 'index.php?p=admin_settings',   'label' => 'Paramètres',        'icon' => '🔧'],
        ];

