    {
        $id = \generate_uuid();
        return $this->execute(
            "INSERT OR IGNORE INTO form_owners (id, form_id, email, added_at) VALUES (?, ?, ?, datetime('now'))",
            [$id, $formId, strtolower($email)]
        );
    }

