     */
    public function findPurgeableIds(string $cutoff): array
    {
        $rows = $this->fetchAll(
            "SELECT id FROM submissions
             WHERE status IN ('valide', 'refuse') AND closed_at IS NOT NULL AND closed_at < ?",
            [$cutoff]
        );
        return array_column($rows, 'id');
    }

